using System.ComponentModel;
using System.Net.Http.Json;
using System.Text.Json;
using Microsoft.Extensions.Logging;
using ModelContextProtocol.Server;

[McpServerToolType]
public class ApiTools(HttpClient httpClient, ILogger<ApiTools> logger)
{
    private static readonly JsonSerializerOptions JsonOptions = new()
    {
        WriteIndented = true
    };

    [McpServerTool, Description("Fetch data from an external API endpoint and return the JSON response.")]
    public async Task<string> FetchApi(
        [Description("The full URL of the API endpoint to call (e.g. https://api.example.com/data)")] string url,
        CancellationToken cancellationToken = default)
    {
        logger.LogInformation("Fetching API: {Url}", url);

        var response = await httpClient.GetAsync(url, cancellationToken);
        response.EnsureSuccessStatusCode();

        var json = await response.Content.ReadFromJsonAsync<JsonElement>(cancellationToken);
        return JsonSerializer.Serialize(json, JsonOptions);
    }
}

using System.ComponentModel;
using Microsoft.Extensions.AI;
using ModelContextProtocol.Server;

[McpServerPromptType]
public static class SummarizationPrompts
{
    [McpServerPrompt, Description("Summarize the provided content into a concise paragraph.")]
    public static ChatMessage Summarize(
        [Description("The text content to summarize")] string content) =>
        new(ChatRole.User, $"Summarize the following content into a concise paragraph:\n\n{content}");

    [McpServerPrompt, Description("Summarize the provided content as a bullet-point list of key takeaways.")]
    public static ChatMessage SummarizeBullets(
        [Description("The text content to summarize as bullet points")] string content) =>
        new(ChatRole.User, $"Summarize the following content as a bullet-point list of key takeaways:\n\n{content}");
}

